const style=document.createElement('style');style.textContent=`#reports-dialog{width:min(1060px,94vw);height:min(760px,90vh);max-width:94vw;max-height:90vh;padding:24px;overflow:hidden;box-sizing:border-box;border:1px solid var(--line);border-radius:18px;background:#faf6ed;color:#1c3338}#reports-dialog::backdrop{background:#182c3566;backdrop-filter:blur(5px)}#reports-dialog header{position:static;display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:18px}#reports-dialog h2{margin:0}#reports-dialog nav select{flex:1;min-width:0;width:auto}#reports-dialog nav button{flex:none;white-space:nowrap}#reports-dialog nav{display:flex;gap:8px;margin-bottom:14px}#reports-dialog button,#reports-dialog select{border:1px solid #ccd2ca;border-radius:8px;padding:9px 12px;color:inherit;background:#fff9;cursor:pointer}#reports-dialog .report-layout{display:grid;grid-template-columns:245px 1fr;gap:22px;height:calc(100% - 110px)}#reports-list{overflow:auto}#reports-list button{width:100%;text-align:left;margin-bottom:8px;line-height:1.6}#reports-list button[aria-current=true]{background:#e0e9dc;border-color:#68826c}#reports-dialog small{display:block;color:#5d7377}#report-reading{overflow:auto;padding:0 12px}#report-content{font-size:14px;line-height:1.9;overflow-wrap:anywhere}#report-content p{white-space:pre-wrap}#report-content a{color:#316e85;text-decoration:underline}#report-content h1{font-size:24px}#report-content h2{font-size:20px;margin-top:22px}#report-content h3{font-size:17px}#report-content li{margin:7px 0;list-style-position:inside}#report-message{color:#6b746f}@media(max-width:650px){#reports-dialog .report-layout{grid-template-columns:1fr;grid-template-rows:150px 1fr}#reports-dialog{padding:16px}}`;
document.head.append(style);
const dialog=document.createElement('dialog');dialog.id='reports-dialog';dialog.setAttribute('aria-label','报告');dialog.innerHTML='<header><h2>报告</h2><button id="reports-close" aria-label="关闭报告">关闭</button></header><nav><select id="report-kind" aria-label="报告类别"><option value="morning">科技与 AI 早报</option><option value="projects">项目进展日报</option></select><button id="reports-refresh">刷新</button></nav><div class="report-layout"><section id="reports-list" aria-label="历史报告"></section><article id="report-reading"><p id="report-message" role="status"></p><button id="report-download" hidden>下载 Markdown</button><div id="report-content"></div></article></div>';document.body.append(dialog);
const $=s=>dialog.querySelector(s);let reports=[],current=null,generation=0;
function inline(el,text){const regex=/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)|\*\*([^*]+)\*\*|`([^`]+)`/g;let start=0;for(const m of text.matchAll(regex)){el.append(document.createTextNode(text.slice(start,m.index)));const part=document.createElement(m[1]?'a':m[3]?'strong':'code');part.textContent=m[1]||m[3]||m[4];if(m[1]){part.href=m[2];part.target='_blank';part.rel='noopener noreferrer';}el.append(part);start=m.index+m[0].length;}el.append(document.createTextNode(text.slice(start)));}
function render(content){const out=$('#report-content');out.replaceChildren();for(const line of content.split('\n')){if(!line.trim())continue;const heading=/^(#{1,3})\s+(.+)/.exec(line),bullet=/^[-*]\s+(.+)/.exec(line);const el=document.createElement(heading?'h'+heading[1].length:bullet?'li':'p');inline(el,heading?heading[2]:bullet?bullet[1]:line);out.append(el);}}
async function request(query=''){const r=await fetch('/api/reports'+query);if(!r.ok)throw Error('报告读取失败，请刷新重试。');return r.json();}
async function read(report){const token=++generation;current=null;$('#report-download').hidden=true;$('#report-content').replaceChildren();$('#report-message').textContent='正在读取…';for(const b of $('#reports-list').children)b.setAttribute('aria-current',String(b.dataset.name===report.name));try{const data=await request('?'+new URLSearchParams({kind:report.kind,name:report.name}));if(token!==generation)return;current=data;render(data.content);$('#report-message').textContent=report.date+' · '+report.edition;$('#report-download').hidden=false;$('#report-reading').scrollTop=0;}catch(e){if(token===generation)$('#report-message').textContent=e.message;}}
function list(){generation++;current=null;$('#report-download').hidden=true;$('#report-content').replaceChildren();$('#reports-list').replaceChildren();const filtered=reports.filter(r=>r.kind===$('#report-kind').value);for(const report of filtered){const b=document.createElement('button');b.dataset.name=report.name;b.append(document.createTextNode(report.date));const small=document.createElement('small');small.textContent=report.edition+' · '+Math.ceil(report.bytes/1024)+' KB';b.append(small);b.onclick=()=>read(report);$('#reports-list').append(b);}if(filtered.length)read(filtered[0]);else $('#report-message').textContent='还没有生成此类报告。任务完成后，点击刷新查看。';}
async function refresh(){const token=++generation;$('#report-message').textContent='正在加载报告列表…';try{const data=await request();if(token!==generation)return;reports=data.reports;list();}catch(e){if(token===generation)$('#report-message').textContent=e.message;}}
export function openReports(kind='morning'){if(!dialog.open)dialog.showModal();$('#report-kind').value=kind;refresh();}
$('#reports-close').onclick=()=>dialog.close();$('#reports-refresh').onclick=refresh;$('#report-kind').onchange=list;
$('#report-download').onclick=()=>{if(!current)return;const url=URL.createObjectURL(new Blob([current.content],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=current.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
document.addEventListener('click',e=>{const button=e.target.closest('[data-report-kind]');if(button)openReports(button.dataset.reportKind);});
